<script>
  import { onMount, onDestroy } from 'svelte'
  import { openPlaylist } from '../lib/store.js'
  import TrackContextMenu from '../components/TrackContextMenu.svelte'
  export let playlist
  export let track = null
  export let onTrack = () => {}
  export let onPlay = () => {}
  export let onShuffle = () => {}
  export let onPlayNext = () => {}
  export let onAddToQueue = () => {}
  export let onAddToPlaylist = () => {}
  export let onRemoveTrack = () => {}
  const clean = value => String(value ?? '').replace(/[\\\n\r\t]+/g, ' ').replace(/\s+/g, ' ').trim()
  function close() { openPlaylist.set(null) }
  function onKeydown(event) { if (event.key === 'Escape') { event.preventDefault(); close() } }
  onMount(() => window.addEventListener('keydown', onKeydown))
  onDestroy(() => window.removeEventListener('keydown', onKeydown))
</script>
<svelte:window on:keydown={onKeydown} />
<div class="songpage" role="dialog" aria-modal="true" aria-label={playlist?.title ?? 'Playlist'}>
  <header class="topbar"><button class="icon-btn" on:click={close} aria-label="Back" title="Back (Esc)">←</button><div class="crumb"><span class="live-dot"></span> PLAYLIST</div><button class="exit" on:click={close} aria-label="Exit" title="Exit (Esc)">Exit</button></header>
  <div class="layout">
    <aside class="details"><div class="cover">{#if playlist?.thumbnail}<img src={playlist.thumbnail} referrerpolicy="no-referrer" alt="{clean(playlist.title)} artwork" />{:else}<span>♫</span>{/if}</div><p class="eyebrow">YOUR COLLECTION</p><h1>{clean(playlist?.title) || 'Playlist'}</h1><p class="summary">{playlist?.tracks?.length ?? 0} songs <span>•</span> Curated for you</p><div class="actions"><button class="play" on:click={onPlay} aria-label="Play playlist">▶ <span>Play</span></button><button class="action" on:click={onShuffle} aria-label="Shuffle playlist">⇄</button></div></aside>
    <section class="tracks" aria-label="Playlist tracks"><div class="track-head"><span>#</span><span>Title</span><span>Artist</span><span>Album</span><span>Time</span><span></span></div>{#each playlist?.tracks ?? [] as t, i (t.videoId)}<div class="track" role="button" tabindex="0" class:active={track && track.videoId === t.videoId} class:playing={track && track.videoId === t.videoId} on:click={() => onTrack(t, i)} on:keydown={(event) => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); onTrack(t, i) } }}><span class="num">{#if track && track.videoId === t.videoId}<span class="equalizer"><i></i><i></i><i></i></span>{:else}{i + 1}{/if}</span><span class="meta"><span class="title">{clean(t.title)}</span></span><span class="artist">{clean(t.artist) || '—'}</span><span class="album">{clean(t.album) || '—'}</span><span class="dur">{t.duration || '—'}</span><TrackContextMenu track={t} owned={playlist?.owned} onPlayNext={onPlayNext} onAddToQueue={onAddToQueue} onAddToPlaylist={onAddToPlaylist} onRemove={onRemoveTrack} /></div>{/each}</section>
  </div>
</div>
<style>
.songpage{position:fixed;inset:0;z-index:10;display:flex;flex-direction:column;overflow:hidden;padding:22px 42px;color:#f4f4f5;background:radial-gradient(ellipse at 18% 18%,#302843 0%,transparent 38%),radial-gradient(ellipse at 88% 100%,#1f3034 0%,transparent 42%),#09090b;font-family:Inter,ui-sans-serif,system-ui,sans-serif}.topbar{display:flex;align-items:center;gap:18px;flex:0 0 auto;padding:0 0 18px;border-bottom:1px solid #ffffff14}.icon-btn,.exit{color:#f4f4f5;background:#ffffff0b;border:1px solid #ffffff29;border-radius:10px;cursor:pointer;transition:.2s;backdrop-filter:blur(20px)}.icon-btn{width:42px;height:42px;font-size:1.25rem}.exit{padding:9px 19px}.icon-btn:hover,.exit:hover{background:#ffffff1f}.crumb{flex:1;color:#a1a1aa;font-size:.7rem;font-weight:700;letter-spacing:.17em}.live-dot{display:inline-block;width:6px;height:6px;margin-right:8px;border-radius:50%;background:#f87171;box-shadow:0 0 12px #f87171}.layout{display:grid;grid-template-columns:minmax(240px,30%) 1fr;gap:clamp(28px,5vw,70px);min-height:0;flex:1;margin:28px auto 0;width:min(1240px,100%)}.details{padding:10px 0}.cover{width:min(100%,310px);aspect-ratio:1;display:grid;place-items:center;border-radius:18px;overflow:hidden;background:linear-gradient(135deg,#252331,#4d3640);box-shadow:0 24px 70px #0007}.cover img{width:100%;height:100%;object-fit:cover}.cover span{color:#fff;font-size:8rem}.eyebrow{margin:26px 0 7px;color:#a1a1aa;font-size:.68rem;font-weight:700;letter-spacing:.16em}h1{margin:0;color:#fafafa;font-size:clamp(1.75rem,4vw,3.2rem);line-height:1.04}.summary{margin:12px 0 22px;color:#a1a1aa;font-size:.9rem}.summary span{margin:0 5px;color:#71717a}.actions{display:flex;gap:9px}.play,.action{border:0;cursor:pointer;transition:.2s}.play{padding:11px 20px;border-radius:22px;color:#161616;background:#fafafa;font-weight:700}.action{width:44px;border-radius:50%;color:#eee;background:#ffffff17;font-size:1rem}.tracks{min-height:0;overflow:auto;padding:3px 7px 20px 0;scrollbar-color:#45454f transparent}.track-head,.track{display:grid;grid-template-columns:38px minmax(160px,1.35fr) minmax(130px,1fr) minmax(120px,1fr) 58px 44px;gap:14px;align-items:center}.track-head{padding:12px 14px;border-bottom:1px solid #ffffff1a;color:#71717a;font-size:.68rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase}.track{width:100%;box-sizing:border-box;padding:13px 14px;border:0;border-radius:10px;color:#e4e4e7;background:transparent;text-align:left;font:inherit;cursor:pointer}.track:nth-child(odd){background:#ffffff05}.track:hover{background:#ffffff12}.track.active{background:#ab8bff29}.num{color:#71717a;font-variant-numeric:tabular-nums}.meta{display:flex;min-width:0;flex-direction:column}.title{overflow:hidden;color:#f4f4f5;font-size:.94rem;font-weight:600;text-overflow:ellipsis;white-space:nowrap}.artist,.album,.dur{color:#a1a1aa;font-size:.83rem}  .artist{margin-top:0}.album{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.dur{text-align:right;font-variant-numeric:tabular-nums}.equalizer{display:inline-flex;align-items:end;gap:2px;height:15px}.equalizer i{width:3px;height:100%;border-radius:2px;background:#c4b5fd;animation:bounce .75s ease-in-out infinite alternate}.equalizer i:nth-child(2){height:65%;animation-delay:-.35s}.equalizer i:nth-child(3){height:82%;animation-delay:-.15s}@keyframes bounce{to{height:28%}}@media(max-width:720px){.songpage{padding:16px}.layout{display:block;overflow:auto;margin-top:18px}.details{padding:0 0 22px}.cover{width:150px}.tracks{overflow:visible}.track-head,.track{grid-template-columns:28px minmax(140px,1fr) 58px 44px}.track-head span:nth-child(4),.album{display:none}.track-head span:nth-child(3){display:block}}
</style>
